// Combine master pool
const combined = [...TV_SHOWS, ...ACCLAIMED_TV_SERIES];
const seenSlugs = new Set();
const finalTvPool = [];

function addShow(show) {
  const slug = show.slug || show.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  if (!seenSlugs.has(slug)) {
    seenSlugs.add(slug);
    finalTvPool.push({
      ...show,
      slug: slug,
      ratings: show.ratings || {
        Acting: (4.4 + Math.random() * 0.6).toFixed(1) + '/5',
        Directing: (4.5 + Math.random() * 0.5).toFixed(1) + '/5',
        Writing: (4.4 + Math.random() * 0.6).toFixed(1) + '/5',
        Cinematography: (4.5 + Math.random() * 0.5).toFixed(1) + '/5',
        Pacing: (4.2 + Math.random() * 0.6).toFixed(1) + '/5',
        Soundtrack: (4.5 + Math.random() * 0.5).toFixed(1) + '/5'
      }
    });
  }
}

combined.forEach(addShow);
REMAINING_TITLES.forEach(addShow);

